const FIELD_META = {"ce": "Teknik Komputer", "cs": "Ilmu Komputer", "se": "Rekayasa Perangkat Lunak", "is": "Sistem Informasi", "it": "Teknologi Informasi"};

/* ---------- util ---------- */
const $ = (s, r=document) => r.querySelector(s);
const $$ = (s, r=document) => Array.from(r.querySelectorAll(s));
const esc = s => s.replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const safe = { get(k){ try{ return localStorage.getItem(k); }catch(e){ return null; } }, set(k,v){ try{ localStorage.setItem(k,v); }catch(e){} } };

/* ---------- tema ---------- */
(function(){
  const btn = $('#themeBtn'); const root = document.documentElement;
  const modes = ['auto','light','dark']; const label = {auto:'otomatis', light:'terang', dark:'gelap'};
  let m = safe.get('peta-theme'); if(!modes.includes(m)) m = 'auto';
  function apply(){ if(m==='auto') root.removeAttribute('data-theme'); else root.setAttribute('data-theme', m); btn.textContent = 'Tema: ' + label[m]; }
  btn.addEventListener('click', () => { m = modes[(modes.indexOf(m)+1)%3]; safe.set('peta-theme', m); apply(); });
  apply();
})();

/* ---------- laci navigasi (layar sempit) ---------- */
(function(){
  const side = $('#side'), scrim = $('#scrim'), mb = $('#menuBtn');
  const set = o => { side.classList.toggle('open', o); scrim.classList.toggle('show', o); mb.setAttribute('aria-expanded', o); };
  mb.addEventListener('click', () => set(!side.classList.contains('open')));
  scrim.addEventListener('click', () => set(false));
  $$('#side a').forEach(a => a.addEventListener('click', () => set(false)));
  document.addEventListener('keydown', e => { if(e.key==='Escape') set(false); });
})();

/* ---------- penanda bagian aktif ---------- */
(function(){
  const links = new Map($$('#side a').map(a => [a.getAttribute('href').slice(1), a]));
  const secs = $$('section[id]');
  const io = new IntersectionObserver(es => {
    es.forEach(e => { if(e.isIntersecting){ links.forEach(a => a.classList.remove('on')); const a = links.get(e.target.id); if(a) a.classList.add('on'); } });
  }, { rootMargin:'-15% 0px -70% 0px' });
  secs.forEach(s => io.observe(s));
})();

/* ---------- tooltip ---------- */
const tip = $('#tip'); let tipEl = null;
function showTip(el){
  const t = el.getAttribute('data-tip'); if(!t) return;
  const head = el.getAttribute('data-tiphead');
  tip.innerHTML = (head ? '<b>'+esc(head)+'</b>' : '') + esc(t);
  tip.classList.add('show'); tipEl = el;
  const r = el.getBoundingClientRect(); const tr = tip.getBoundingClientRect();
  let x = Math.min(Math.max(8, r.left + r.width/2 - tr.width/2), window.innerWidth - tr.width - 8);
  let y = r.bottom + 8; if(y + tr.height > window.innerHeight - 8) y = Math.max(8, r.top - tr.height - 8);
  tip.style.left = x + 'px'; tip.style.top = y + 'px';
}
function hideTip(){ tip.classList.remove('show'); tipEl = null; }
document.addEventListener('mouseover', e => { const el = e.target.closest('[data-tip]'); if(el) showTip(el); else if(tipEl) hideTip(); });
document.addEventListener('focusin', e => { const el = e.target.closest('[data-tip]'); if(el) showTip(el); });
document.addEventListener('focusout', hideTip);
document.addEventListener('click', e => { const el = e.target.closest('[data-tip]'); if(el && (tipEl !== el)) showTip(el); else if(!el) hideTip(); });
window.addEventListener('scroll', hideTip, { passive:true });
document.addEventListener('keydown', e => { if(e.key==='Escape') hideTip(); });

/* ---------- glosarium otomatis (kemunculan pertama per bagian) ---------- */
(function(){
  const terms = Object.keys(GLOSS).filter(t => GLOSS[t]).sort((a,b) => b.length - a.length);
  const re = t => new RegExp('(^|[^\\p{L}\\p{N}])(' + t.replace(/[.*+?^${}()|[\]\\\/]/g,'\\$&') + ')(?![\\p{L}\\p{N}])', t.length <= 4 ? 'u' : 'iu');
  const used = new Map();
  const scopes = $$('.lead, .card p, .t-desc, figcaption, .fdesc, .fq, .topic .d, .md, .mtab td, .ov td, .use, .atag, .pdesc, .callout p, .ladder small');
  terms.forEach(t => {
    const rx = re(t);
    for(const sc of scopes){
      const sec = sc.closest('section'); const key = sec ? sec.id : 'x';
      if(!used.has(key)) used.set(key, new Set());
      if(used.get(key).has(t)) continue;
      const w = document.createTreeWalker(sc, NodeFilter.SHOW_TEXT, { acceptNode: n => n.parentElement.closest('.term, [data-tip], svg, code') ? NodeFilter.FILTER_REJECT : NodeFilter.FILTER_ACCEPT });
      let n, done = false;
      while((n = w.nextNode())){
        const m = rx.exec(n.nodeValue); if(!m) continue;
        const start = m.index + m[1].length, end = start + m[2].length;
        const span = document.createElement('span'); span.className = 'term'; span.tabIndex = 0;
        span.setAttribute('data-tip', GLOSS[t]); span.setAttribute('data-tiphead', t); span.textContent = n.nodeValue.slice(start, end);
        const after = n.splitText(start); after.nodeValue = after.nodeValue.slice(end - start);
        n.parentNode.insertBefore(span, after);
        used.get(key).add(t); done = true; break;
      }
      if(done) break;
    }
  });
})();

/* ---------- pencarian topik bidang ---------- */
(function(){
  const inp = $('#fsearch'), cnt = $('#fcount'); if(!inp) return;
  const topics = $$('.topic'); const areas = $$('details.area');
  function run(){
    const q = inp.value.trim().toLowerCase(); let n = 0;
    topics.forEach(t => { const ok = !q || t.textContent.toLowerCase().includes(q); t.hidden = !ok; if(ok && q) n++; });
    areas.forEach(a => { const vis = $$('.topic', a).some(t => !t.hidden); a.hidden = !vis; a.open = q ? vis : false; });
    $$('.field').forEach(f => { f.hidden = !!q && !$$('.topic', f).some(t => !t.hidden); });
    cnt.textContent = q ? n + ' topik cocok' : topics.length + ' topik';
  }
  inp.addEventListener('input', run); run();
})();

/* ---------- tabel metode ---------- */
(function(){
  const box = $('#mfilters'), body = $('#mbody'); let cur = 'ALL';
  const names = {CE:'Teknik Komputer', CS:'Ilmu Komputer', SE:'RPL', IS:'Sistem Informasi', IT:'Teknologi Informasi'};
  const mk = (id, text) => { const b = document.createElement('button'); b.type='button'; b.className='chip'; b.textContent = text; b.setAttribute('aria-pressed', id===cur); b.addEventListener('click', () => { cur = id; $$('button.chip', box).forEach(x => x.setAttribute('aria-pressed', x===b)); draw(); }); box.appendChild(b); };
  mk('ALL','Semua'); Object.keys(names).forEach(k => mk(k, names[k]));
  function draw(){
    const rows = METHODS.filter(m => cur==='ALL' || m[4].split(',').includes(cur));
    body.innerHTML = rows.map(m => '<tr><td>'+esc(m[0])+'</td><td>'+esc(m[1])+'</td><td>'+esc(m[2])+'</td><td>'+esc(m[3])+'</td><td class="tagdots">'+m[4].split(',').map(t => '<span class="tg '+t.toLowerCase()+'">'+t+'</span>').join('')+'</td></tr>').join('');
  }
  draw();
})();

/* ---------- tabel notasi ---------- */
(function(){
  const body = $('#nbody'), inp = $('#nsearch'), cnt = $('#ncount'), chips = $('#catchips');
  let cat = 'all'; const open = new Set();
  const plain = h => { const d = document.createElement('div'); d.innerHTML = h; return d.textContent; };
  const idx = NOTES.map((r,i) => ({ r, i, text:(plain(r[1])+' '+r[2]+' '+plain(r[3])+' '+r[5]+' '+r[6]).toLowerCase() }));
  const counts = {}; NOTES.forEach(r => counts[r[0]] = (counts[r[0]]||0)+1);
  const mkChip = (id, label, k) => { const b = document.createElement('button'); b.type='button'; b.className='chip'; b.dataset.cat = id; b.setAttribute('aria-pressed', id===cat); b.innerHTML = esc(label)+'<span class="k">'+k+'</span>'; b.addEventListener('click', () => { cat = id; $$('button.chip', chips).forEach(x => x.setAttribute('aria-pressed', x===b)); draw(); }); chips.appendChild(b); };
  mkChip('all','Semua',NOTES.length); CATS.forEach(c => mkChip(c[0], c[1], counts[c[0]]||0));
  function draw(){
    const q = inp.value.trim().toLowerCase();
    const rows = idx.filter(x => (cat==='all' || x.r[0]===cat) && (!q || x.text.includes(q)));
    cnt.textContent = rows.length + ' dari ' + NOTES.length + ' notasi';
    if(!rows.length){ body.innerHTML = '<tr><td colspan="4" class="empty">Tidak ada notasi yang cocok. Coba kata kunci lain atau pilih "Semua".</td></tr>'; return; }
    body.innerHTML = rows.map(x => {
      const r = x.r, o = open.has(x.i);
      let h = '<tr class="nrow" tabindex="0" data-i="'+x.i+'" aria-expanded="'+o+'"><td class="sym">'+r[1]+'</td><td class="rd">'+esc(r[2])+'</td><td>'+esc(r[3])+'</td><td class="tg-c">'+r[6].split(',').map(t => '<span class="tg">'+esc(t.trim())+'</span>').join('')+'</td></tr>';
      if(o) h += '<tr class="det"><td colspan="4"><div class="det-grid"><div><h5>Contoh</h5><div>'+r[4]+'</div></div><div><h5>LaTeX</h5><code>'+esc(r[5])+'</code><button type="button" class="btn cp" data-latex="'+x.i+'">Salin</button></div><div><h5>Kategori</h5><div>'+esc((CATS.find(c => c[0]===r[0])||[])[1]||'')+'</div></div></div></td></tr>';
      return h;
    }).join('');
  }
  function toggle(tr){ const i = +tr.dataset.i; open.has(i) ? open.delete(i) : open.add(i); draw(); const again = $('tr.nrow[data-i="'+i+'"]', body); if(again) again.focus({preventScroll:true}); }
  body.addEventListener('click', e => {
    const cp = e.target.closest('[data-latex]');
    if(cp){ const t = NOTES[+cp.dataset.latex][5]; const done = () => { cp.textContent = 'Tersalin'; setTimeout(() => cp.textContent = 'Salin', 1400); };
      const fb = () => { const code = cp.previousElementSibling; const rg = document.createRange(); rg.selectNodeContents(code); const s = getSelection(); s.removeAllRanges(); s.addRange(rg); cp.textContent = 'Pilih lalu salin'; };
      if(navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(t).then(done, fb); else fb(); return; }
    const tr = e.target.closest('tr.nrow'); if(tr) toggle(tr);
  });
  body.addEventListener('keydown', e => { if((e.key==='Enter' || e.key===' ') && e.target.matches('tr.nrow')){ e.preventDefault(); toggle(e.target); } });
  inp.addEventListener('input', draw); draw();
})();

