/* ---------- bedah rumus ---------- */
(function(){
  const box = $('#formulas');
  box.innerHTML = FORMULAS.map((f,fi) => '<div class="formula"><h3>'+esc(f.title)+'</h3><p>'+esc(f.note)+'</p><div class="fline" role="group" aria-label="'+esc(f.title)+'">'+f.tokens.map((t,ti) => t[1] ? '<span class="tok" tabindex="0" data-f="'+fi+'" data-t="'+ti+'" data-tip="'+esc(t[1])+'" data-tiphead="'+esc(t[2]||'')+'">'+t[0]+'</span>' : '<span>'+t[0]+'</span>').join('')+'</div><div class="tokexp" id="tx'+fi+'">Pilih bagian rumus di atas.</div></div>').join('');
  box.addEventListener('mouseover', e => { const t = e.target.closest('.tok'); if(t) pick(t); });
  box.addEventListener('focusin', e => { const t = e.target.closest('.tok'); if(t) pick(t); });
  box.addEventListener('click', e => { const t = e.target.closest('.tok'); if(t) pick(t); });
  function pick(t){ const f = t.dataset.f; $$('.tok[data-f="'+f+'"]', box).forEach(x => x.classList.toggle('act', x===t)); $('#tx'+f).innerHTML = '<b>'+t.innerHTML+'</b> '+esc(t.getAttribute('data-tiphead') ? t.getAttribute('data-tiphead')+': ' : '')+esc(t.getAttribute('data-tip')); }
})();

/* ---------- katalog kartu: filter kelompok + pencarian ---------- */
(function(){
  $$('.cat').forEach(cat => {
    const cards = $$('.ccard', cat), bar = $('.cbar', cat), inp = $('input', bar), box = $('.cchips', bar), cnt = $('.ccount', bar);
    const groups = Array.from(new Set(cards.map(c => c.dataset.group))); let cur = 'ALL';
    const mk = (id, label) => { const b = document.createElement('button'); b.type='button'; b.className='chip'; b.textContent = label; b.setAttribute('aria-pressed', id===cur);
      b.addEventListener('click', () => { cur = id; $$('button.chip', box).forEach(x => x.setAttribute('aria-pressed', x===b)); run(); }); box.appendChild(b); };
    mk('ALL','Semua'); groups.forEach(g => mk(g, g));
    function run(){ const q = inp.value.trim().toLowerCase(); let n = 0;
      cards.forEach(c => { const ok = (cur==='ALL' || c.dataset.group===cur) && (!q || c.textContent.toLowerCase().includes(q)); c.hidden = !ok; if(ok) n++; });
      cnt.textContent = n + ' dari ' + cards.length; }
    inp.addEventListener('input', run); run();
  });
})();

/* ---------- peta area: filter disiplin, jenis, pencarian ---------- */
(function(){
  const root = $('#areas'); if(!root) return;
  const cards = $$('.acard', root), inp = $('#asearch'), cnt = $('#acount');
  const state = { disc:'ALL', kind:'ALL' };
  function chips(boxId, key, items){
    const box = $(boxId); items.forEach(([id, label]) => { const b = document.createElement('button'); b.type='button'; b.className='chip'; b.textContent = label; b.setAttribute('aria-pressed', id===state[key]);
      b.addEventListener('click', () => { state[key] = id; $$('button.chip', box).forEach(x => x.setAttribute('aria-pressed', x===b)); run(); }); box.appendChild(b); });
  }
  chips('#adisc', 'disc', [['ALL','Semua'],['CE','CE'],['CS','CS'],['SE','SE'],['IS','IS'],['IT','IT']]);
  chips('#akind', 'kind', [['ALL','Semua'],['metode','Metode dan model'],['domain','Domain dan tugas'],['sistem','Sistem dan infrastruktur']]);
  function run(){ const q = inp.value.trim().toLowerCase(); let n = 0;
    cards.forEach(c => { const ok = (state.disc==='ALL' || c.dataset.disc.split(' ').includes(state.disc)) && (state.kind==='ALL' || c.dataset.kind===state.kind) && (!q || c.textContent.toLowerCase().includes(q)); c.hidden = !ok; if(ok) n++; });
    cnt.textContent = n + ' dari ' + cards.length + ' area'; }
  inp.addEventListener('input', run); run();
})();

/* ---------- irisan: filter pasangan disiplin ---------- */
(function(){
  const box = $('#pfilter'), grid = $('#pairs'); if(!box) return; let cur = 'ALL';
  [['ALL','Semua pasangan'],['ce','CE'],['cs','CS'],['se','SE'],['is','IS'],['it','IT']].forEach(([id, label]) => {
    const b = document.createElement('button'); b.type='button'; b.className='chip'; b.textContent = label; b.setAttribute('aria-pressed', id===cur);
    b.addEventListener('click', () => { cur = id; $$('button.chip', box).forEach(x => x.setAttribute('aria-pressed', x===b)); $$('.pcard', grid).forEach(c => { c.hidden = !(cur==='ALL' || c.dataset.p.split(' ').includes(cur)); }); });
    box.appendChild(b); });
})();


/* ---------- tombol kembali ke atas ---------- */
(function(){
  const b = $('#toTop'); if(!b) return;
  const reduce = matchMedia('(prefers-reduced-motion: reduce)');
  let ticking = false;
  function update(){ b.hidden = window.scrollY < 600; ticking = false; }
  window.addEventListener('scroll', () => { if(!ticking){ ticking = true; requestAnimationFrame(update); } }, {passive:true});
  b.addEventListener('click', () => {
    window.scrollTo({ top:0, behavior: reduce.matches ? 'auto' : 'smooth' });
    const first = $('.home-link') || $('main'); if(first && first.focus){ first.setAttribute('tabindex','-1'); first.focus({preventScroll:true}); }
  });
  update();
})();
